<?php
namespace qqworld_collector\module\auto_save_attachments; use qqworld_collector\lib; class image_paste extends lib { var $options; public function __construct() { add_action( 'wp_ajax_qqworld-collector-image-paste', array($this, 'paste') ); add_action( 'wp_ajax_nopriv_qqworld-collector-image-paste', array($this, 'paste') ); add_action( 'admin_notices', array($this, 'admin_notices') ); } public function init() { if ($this->options->qc_asa_general_paste_image) $this->add_buttons(); } public function add_buttons() { if ( get_user_option('rich_editing') == 'true') { add_filter("mce_external_plugins", array($this, 'add_tinymce_plugin') ); add_filter('mce_buttons', array($this, 'register_button') ); } } public function register_button($buttons) { array_push($buttons, 'separator', 'tinyimagepaste'); return $buttons; } public function add_tinymce_plugin($plugin_array) { $plugin_array['tinyimagepaste'] = QQWORLD_COLLECTOR_URL . 'js/image-paste-editor-plugin.js'; return $plugin_array; } public function paste() { $result = array('error'=>''); list($data, $image) = explode(';',$_REQUEST['dataurl']); list($field, $type) = explode(':',$data); list($encoding, $content) = explode(',',$image); if ($type=='image/png') $extension='png'; $name = md5($_REQUEST['dataurl']); if (!$extension) { $result['error'] = __('Could not determine image extension type.', $this->text_domain); } else { $file = base64_decode($content); list($real_width, $real_height) = getimagesizefromstring($file); $remote_attachment = array( 'url' => '', 'base64' => 1, 'filename' => $name.'.'.$extension, 'title' => '', 'alt' => '', 'real_width' => $real_width, 'real_height' => $real_height, 'type' => $type, 'file' => $file, 'crc' => '', 'too-small' => 0, 'delete' => 0, 'ignore' => 0, 'downloaded' => 0 ); $remote_attachment = $this->core->save_to_local('image', $remote_attachment, $_POST['post_id']); $result['url'] = $remote_attachment['sizes']['full']['url']; $result['attachment_id'] = isset($remote_attachment['attachment_id']) ? $remote_attachment['attachment_id'] : 0; if ($this->options->qc_asa_general_paste_image_then_convert) { $convert_to = $this->options->qc_asa_filter_convert_file_type_jpg ? 'webp' : 'jpeg'; $attachment_id = apply_filters( 'qqworld-collector-convert-file-format-to', $result['attachment_id'], $convert_to, 'override' ); $result['url'] = wp_get_attachment_url($attachment_id); } elseif ($this->options->qc_asa_filter_convert_file_type_png) { $attachment_id = apply_filters( 'qqworld-collector-convert-file-format-to', $result['attachment_id'], 'webp', 'override' ); $result['url'] = wp_get_attachment_url($attachment_id); } } print json_encode($result, JSON_INVALID_UTF8_IGNORE); exit; } public function admin_notices() { $errors = array(); $upload = wp_upload_dir(); if ($upload['error']) $errors[]=$upload['error']; if (count($errors)) { $messages = array(); foreach ($errors as $error) $messages[] = 'Image Paste: '.$error; printf( '<div class="notice notice-error"><p>%s</p></div>', implode('<br />', $messages) ); } } } ?>